sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float brightness;
uniform float contrast;
uniform float style;

half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) {
        return half4(0.0);
    }
    half3 rgb = c.rgb / c.a;
    if (style > 0.5) rgb = rgb + half(brightness + contrast * (dot(float3(rgb), float3(0.299, 0.587, 0.114)) - 0.5));
    else rgb = (rgb - 0.5) * (1.0 + contrast) + 0.5 + brightness;
    rgb = clamp(rgb, 0.0, 1.0);
    return half4(rgb * c.a, c.a);
}
